#!/usr/bin/env node
// PreToolUse hook (mcp__github__*): refuses a GitHub write whose text carries Claude attribution
// (scripts/claude-attribution.js). The generic GitHub instructions tell a session to end every comment with the
// "Generated by Claude Code" footer; this repo's rule wins (CLAUDE.md § Workflow). Covers PR comments and reviews,
// which the no-claude-identity guard cannot see. Known limit: the GitHub tool adds the footer to a new PR's body on
// the server, after this hook; the guard catches that in CI. Fails closed: exit 2 on bad input or a crash.
'use strict';
const fs = require('fs');
const patterns = require('./claude-attribution');

const deny = (why) => { console.error(`GitHub write denied: ${why}`); process.exit(2); };
const strings = (v) => (typeof v === 'string' ? [v] : v && typeof v === 'object' ? Object.values(v).flatMap(strings) : []);

try {
  const input = JSON.parse(fs.readFileSync(0, 'utf8'));
  const text = strings(input.tool_input).join('\n');
  const found = patterns.filter(([re]) => re.test(text)).map(([, what]) => what);
  if (found.length) deny(`the text has ${found.join(' and ')}. This repo keeps Claude attribution out of PRs and comments: remove those lines and send again (keep a PR body's "Requested by" block).`);
} catch (e) {
  deny(`the attribution check crashed (${e.message}), so it cannot be checked`);
}
